import pytest

from itsdangerous.signer import Signer


def make_signer(**kwargs):
    return Signer(secret_key="fallback-secret", salt="salt", **kwargs)


def test_explicit_empty_bytes_key_is_not_omitted():
    # Requirement: an explicitly supplied empty bytes key is distinct from an
    # omitted None key; with 'none' derivation the explicit key is returned.
    signer = make_signer(key_derivation="none")
    assert signer.derive_key(b"") == b""


def test_omitted_key_uses_last_secret_key():
    signer = make_signer(key_derivation="none")
    assert signer.derive_key() == b"fallback-secret"


def test_none_key_uses_last_secret_key():
    signer = make_signer(key_derivation="none")
    assert signer.derive_key(None) == b"fallback-secret"


def test_explicit_nonempty_bytes_key_returned():
    signer = make_signer(key_derivation="none")
    assert signer.derive_key(b"explicit") == b"explicit"


def test_explicit_str_key_converted_to_bytes():
    signer = make_signer(key_derivation="none")
    assert signer.derive_key("explicit") == b"explicit"


def test_invalid_key_derivation_raises_type_error():
    signer = make_signer(key_derivation="invalid")
    with pytest.raises(TypeError):
        signer.derive_key()

import pytest

from jinja2.filters import do_striptags


class HasHTMLObject:
    def __init__(self, html, text):
        self._html = html
        self._text = text

    def __html__(self):
        return self._html

    def __str__(self):
        return self._text


def test_plain_string_no_tags():
    assert do_striptags("hello world") == "hello world"


def test_plain_string_with_tags():
    assert do_striptags("<p>hello <b>world</b></p>") == "hello world"


def test_empty_string():
    assert do_striptags("") == ""


def test_only_tags():
    assert do_striptags("<div><span></span></div>") == ""


def test_whitespace_collapsed():
    assert do_striptags("<p>a</p>   <p>b</p>") == "a b"


def test_html_protocol_uses_html_not_str():
    obj = HasHTMLObject("<b>from html</b>", "from str")
    assert do_striptags(obj) == "from html"


def test_html_protocol_with_tags_stripped():
    obj = HasHTMLObject("<div>a <i>b</i></div>", "<div>a <i>b</i></div>")
    assert do_striptags(obj) == "a b"


def test_html_protocol_empty_html():
    obj = HasHTMLObject("", "should not appear")
    assert do_striptags(obj) == ""


def test_none_is_stringified():
    assert do_striptags(None) == "None"

import pytest

from jinja2.filters import do_striptags


class HasHTMLObject:
    """Object implementing the HTML protocol via __html__."""

    def __init__(self, html, text):
        self._html = html
        self._text = text

    def __html__(self):
        return self._html

    def __str__(self):
        return self._text


class PlainObject:
    """Object without __html__, only str representation."""

    def __init__(self, text):
        self._text = text

    def __str__(self):
        return self._text


def test_hashtml_uses_html_not_str():
    # Requirement: strip the text returned by __html__, not str(value).
    obj = HasHTMLObject("<p>Hello</p>", "WRONG-STR-VALUE")
    assert do_striptags(obj) == "Hello"


def test_hashtml_with_nested_tags_and_whitespace():
    obj = HasHTMLObject("<div>  <b>a</b>   <i>b</i>  </div>", "ignored")
    assert do_striptags(obj) == "a b"


def test_hashtml_empty_html():
    obj = HasHTMLObject("", "ignored")
    assert do_striptags(obj) == ""


def test_hashtml_only_tags():
    obj = HasHTMLObject("<br/><hr/>", "ignored")
    assert do_striptags(obj) == ""


def test_plain_string_strips_tags():
    assert do_striptags("<p>Hello</p>") == "Hello"


def test_plain_string_collapses_whitespace():
    assert do_striptags("<p>a</p>   <p>b</p>") == "a b"


def test_empty_string():
    assert do_striptags("") == ""


def test_object_without_html_falls_back_to_str():
    obj = PlainObject("<p>Fallback</p>")
    assert do_striptags(obj) == "Fallback"

import pytest

from jinja2.filters import do_dictsort
from jinja2.exceptions import FilterArgumentError


def test_dictsort_default_sorts_by_key_case_insensitive():
    data = {"B": 2, "a": 1, "C": 3}
    assert do_dictsort(data) == [("a", 1), ("B", 2), ("C", 3)]


def test_dictsort_by_key_explicit():
    data = {"b": 2, "A": 1}
    assert do_dictsort(data, by="key") == [("A", 1), ("b", 2)]


def test_dictsort_by_value_case_insensitive():
    data = {"x": "B", "y": "a", "z": "C"}
    assert do_dictsort(data, by="value") == [("y", "a"), ("x", "B"), ("z", "C")]


def test_dictsort_case_sensitive():
    data = {"b": 1, "A": 2}
    assert do_dictsort(data, case_sensitive=True) == [("A", 2), ("b", 1)]


def test_dictsort_reverse():
    data = {"a": 1, "b": 2, "c": 3}
    assert do_dictsort(data, reverse=True) == [("c", 3), ("b", 2), ("a", 1)]


def test_dictsort_empty_mapping():
    assert do_dictsort({}) == []


@pytest.mark.parametrize("bad_by", ["foo", "", "KEY", "values", "Value", None, 0])
def test_dictsort_invalid_by_raises(bad_by):
    with pytest.raises(FilterArgumentError):
        do_dictsort({"a": 1}, by=bad_by)

