from jinja2.exceptions import FilterArgumentError
from jinja2.filters import do_dictsort


def test_dictsort_invalid_by_does_not_fall_back_to_key_sort():
    # An invalid 'by' must raise rather than silently sorting by key.
    data = {"b": 1, "a": 2}
