    assert do_dictsort(data, by="value", reverse=True) == [("b", 3), ("c", 2), ("a", 1)]

import pytest

from jinja2.filters import do_round
from jinja2.exceptions import FilterArgumentError


def test_common_rounding_default_precision():
    assert do_round(42.55) == 43.0


def test_common_rounding_with_precision():
    assert do_round(42.55, 1) == 42.5
    assert do_round(42.55, 1, "common") == 42.5


def test_floor_rounding():
    assert do_round(42.55, 1, "floor") == 42.5
    assert do_round(42.99, 0, "floor") == 42.0


def test_ceil_rounding():
    assert do_round(42.01, 1, "ceil") == 42.1
    assert do_round(42.01, 0, "ceil") == 43.0


def test_negative_precision():
    assert do_round(1234.0, -2, "floor") == 1200.0
    assert do_round(1234.0, -2, "ceil") == 1300.0


@pytest.mark.parametrize("method", ["round", "up", "down", "nearest", "", "COMMON", "Ceil"])
def test_unsupported_method_raises(method):
    with pytest.raises(FilterArgumentError):
        do_round(42.55, 1, method)


def test_unsupported_method_none_raises():
    with pytest.raises(FilterArgumentError):
        do_round(42.55, 1, None)


def test_unsupported_method_does_not_return_unrounded_value():
    with pytest.raises(FilterArgumentError):
        do_round(42.55, 0, "bogus")

