import pytest

from jinja2 import Environment
from jinja2.filters import sync_do_sum


@pytest.fixture
def env():
    return Environment()


def test_attribute_zero_selects_first_element(env):
    # Requirement: attribute index zero is an explicitly specified index,
    # distinct from no attribute. So index 0 must be looked up on each item.
    items = [(1, 10), (2, 20), (3, 30)]
    assert sync_do_sum(env, items, attribute=0) == 6


def test_attribute_none_sums_items_directly(env):
    # No attribute means sum the items themselves.
    assert sync_do_sum(env, [1, 2, 3]) == 6
    assert sync_do_sum(env, [1, 2, 3], attribute=None) == 6


def test_attribute_one_selects_second_element(env):
    items = [(1, 10), (2, 20), (3, 30)]
    assert sync_do_sum(env, items, attribute=1) == 60


def test_attribute_zero_with_start(env):
    items = [(1, 10), (2, 20)]
    assert sync_do_sum(env, items, attribute=0, start=100) == 103


def test_empty_iterable_returns_start(env):
    assert sync_do_sum(env, []) == 0
    assert sync_do_sum(env, [], start=5) == 5
    assert sync_do_sum(env, [], attribute=0, start=7) == 7


def test_string_attribute_still_works(env):
    class Item:
        def __init__(self, price):
            self.price = price

    items = [Item(1), Item(2), Item(3)]
    assert sync_do_sum(env, items, attribute="price") == 6


def test_attribute_zero_via_template(env):
    tmpl = env.from_string("{{ items|sum(attribute=0) }}")
    assert tmpl.render(items=[(1, 10), (2, 20)]) == "3"

import pytest

from jinja2 import Environment
from jinja2.filters import sync_do_sum


@pytest.fixture
def env():
    return Environment()


def test_attribute_zero_selects_first_element(env):
    # Requirement: attribute index 0 is an explicit index, distinct from None.
    items = [(1, 10), (2, 20), (3, 30)]
    assert sync_do_sum(env, items, attribute=0) == 6


def test_attribute_zero_differs_from_no_attribute(env):
    items = [(1, 10), (2, 20), (3, 30)]
    # No attribute sums the tuples themselves (concatenation), not index 0.
    assert sync_do_sum(env, items, attribute=0) == 6
    assert sync_do_sum(env, items, attribute=None) == (1, 10, 2, 20, 3, 30)


def test_attribute_zero_with_start(env):
    items = [(1, 10), (2, 20)]
    assert sync_do_sum(env, items, attribute=0, start=100) == 103


def test_attribute_zero_on_lists(env):
    items = [[5, 1], [7, 2], [9, 3]]
    assert sync_do_sum(env, items, attribute=0) == 21


def test_empty_iterable_returns_start_with_attribute_zero(env):
    assert sync_do_sum(env, [], attribute=0) == 0
    assert sync_do_sum(env, [], attribute=0, start=7) == 7


def test_attribute_zero_on_objects_with_getitem(env):
    class Row:
        def __init__(self, first, second):
            self._values = (first, second)

        def __getitem__(self, index):
            return self._values[index]

    rows = [Row(1, 100), Row(2, 200), Row(3, 300)]
    assert sync_do_sum(env, rows, attribute=0) == 6


def test_attribute_zero_invalid_on_plain_ints(env):
    # Specified invalid input: index 0 cannot be looked up on ints.
    with pytest.raises(TypeError):
        sync_do_sum(env, [1, 2, 3], attribute=0)

import pytest

from jinja2 import Environment
from jinja2.filters import sync_do_sum


@pytest.fixture
def env():
    return Environment()


def test_sum_attribute_zero_tuples(env):
    # attribute=0 is an explicitly specified index, so it must sum the
    # first element of each tuple, not the tuples themselves.
    data = [(1, 10), (2, 20), (3, 30)]
    assert sync_do_sum(env, data, attribute=0) == 6


def test_sum_attribute_zero_lists(env):
    data = [[5, 100], [7, 200], [9, 300]]
    assert sync_do_sum(env, data, attribute=0) == 21


def test_sum_attribute_zero_with_start(env):
    data = [(1, 10), (2, 20)]
    assert sync_do_sum(env, data, attribute=0, start=100) == 103


def test_sum_attribute_zero_empty(env):
    # Empty sequence returns start regardless of attribute.
    assert sync_do_sum(env, [], attribute=0) == 0
    assert sync_do_sum(env, [], attribute=0, start=42) == 42


def test_sum_no_attribute_sums_items(env):
    # attribute=None means no attribute lookup; items are summed directly.
    assert sync_do_sum(env, [1, 2, 3]) == 6
    assert sync_do_sum(env, [1, 2, 3], attribute=None) == 6


def test_sum_attribute_one(env):
    data = [(1, 10), (2, 20), (3, 30)]
    assert sync_do_sum(env, data, attribute=1) == 60


def test_sum_string_attribute(env):
    class Item:
        def __init__(self, price):
            self.price = price

    data = [Item(1.5), Item(2.5), Item(3.0)]
    assert sync_do_sum(env, data, attribute="price") == 7.0


def test_sum_start_default(env):
    assert sync_do_sum(env, [1, 2, 3], start=10) == 16


def test_sum_attribute_zero_in_template(env):
    tmpl = env.from_string("{{ items|sum(attribute=0) }}")
    assert tmpl.render(items=[(1, 10), (2, 20), (3, 30)]) == "6"

import pytest

from click._textwrap import TextWrapper


def make_wrapper(initial="I:", subsequent="S:"):
    return TextWrapper(initial_indent=initial, subsequent_indent=subsequent)


def test_first_line_uses_initial_indent():
    w = make_wrapper()
    assert w.indent_only("hello") == "I:hello"


def test_second_line_uses_subsequent_indent():
    w = make_wrapper()
    assert w.indent_only("first\nsecond") == "I:first\nS:second"


def test_third_and_later_lines_use_subsequent_indent():
    w = make_wrapper()
    assert w.indent_only("a\nb\nc\nd") == "I:a\nS:b\nS:c\nS:d"


def test_empty_text_returns_empty_string():
    w = make_wrapper()
    assert w.indent_only("") == ""


def test_single_line_with_empty_indents():
    w = make_wrapper(initial="", subsequent="")
    assert w.indent_only("only") == "only"


def test_multiline_with_empty_indents():
    w = make_wrapper(initial="", subsequent="")
    assert w.indent_only("one\ntwo\nthree") == "one\ntwo\nthree"


def test_blank_lines_still_get_indent():
    w = make_wrapper()
    assert w.indent_only("a\n\nb") == "I:a\nS:\nS:b"


def test_trailing_newline_does_not_add_extra_line():
    w = make_wrapper()
    # splitlines drops the trailing empty segment
    assert w.indent_only("a\nb\n") == "I:a\nS:b"

import pytest

from itsdangerous.exc import BadSignature
from itsdangerous.signer import Signer


@pytest.fixture
def signer():
    return Signer("secret-key")


def test_valid_signature_accepted(signer):
    signed = signer.sign("payload")
    value, sig = signed.rsplit(b".", 1)
    assert signer.verify_signature(value, sig) is True


def test_corrupted_valid_base64_signature_rejected(signer):
    signed = signer.sign("payload")
    value, sig = signed.rsplit(b".", 1)
    # Flip a byte while keeping the string valid base64.
    corrupted = b"A" + sig[1:]
    assert signer.verify_signature(value, corrupted) is False


@pytest.mark.parametrize(
    "bad_sig",
    [
        b"!!!not-base64!!!",
        b"@@@@@@@@",
        b"abc",  # invalid length / padding
        b"a",
        b"====",
        "not base64 at all",
        "\u00e9\u00e9\u00e9",
    ],
)
def test_malformed_base64_signature_not_accepted(signer, bad_sig):
    assert signer.verify_signature(b"payload", bad_sig) is False


def test_malformed_base64_signature_unsign_raises(signer):
    with pytest.raises(BadSignature):
        signer.unsign(b"payload.!!!not-base64!!!")

