import pytest

from itsdangerous.signer import Signer


@pytest.fixture
def signer():
    return Signer("secret-key")


def test_valid_signature_accepted(signer):
    signed = signer.sign("value")
    sig = signed.rsplit(b".", 1)[1]
    assert signer.verify_signature(b"value", sig) is True


def test_tampered_valid_base64_signature_rejected(signer):
    signed = signer.sign("value")
    sig = signed.rsplit(b".", 1)[1]
    tampered = (b"A" if sig[:1] != b"A" else b"B") + sig[1:]
    assert signer.verify_signature(b"value", tampered) is False


@pytest.mark.parametrize(
    "bad_sig",
    [
        b"not base64!!",
        b"@@@@@@@@",
        b"abc",
        b"a",
        b"====",
        b"ab=c",
        "not base64!!",
        "@@@@@@@@",
        "abc",
    ],
)
def test_malformed_base64_signature_rejected(signer, bad_sig):
    assert signer.verify_signature(b"value", bad_sig) is False


def test_malformed_signature_does_not_verify_any_value(signer):
    assert signer.verify_signature(b"", b"!!!") is False
    assert signer.verify_signature(b"anything", b"%%%") is False


def test_empty_signature_rejected(signer):
    assert signer.verify_signature(b"value", b"") is False


def test_signature_for_different_value_rejected(signer):
    signed = signer.sign("value")
    sig = signed.rsplit(b".", 1)[1]
    assert signer.verify_signature(b"other", sig) is False

import pytest

from jinja2.filters import do_indent


def test_empty_string_default_no_indent():
    # Requirement: default indentation does not add spaces to the empty
    # first/blank line of an empty string.
    assert do_indent("") == ""


def test_empty_string_with_explicit_width_no_indent():
    assert do_indent("", width=2) == ""


def test_empty_string_with_string_width_no_indent():
    assert do_indent("", width="--") == ""


