from datetime import datetime, timedelta, tzinfo

import pytest

from dateutil.tz._common import _validate_fromutc_inputs


class _FixedOffset(tzinfo):
    def __init__(self, offset_minutes):
        self._offset = timedelta(minutes=offset_minutes)

    def utcoffset(self, dt):
        return self._offset

    def dst(self, dt):
        return timedelta(0)

    def tzname(self, dt):
        return "fixed"


class _RecordingTz(tzinfo):
    def __init__(self):
        self.calls = []

    def utcoffset(self, dt):
        return timedelta(0)

    def dst(self, dt):
        return timedelta(0)

    def tzname(self, dt):
        return "recording"

    @_validate_fromutc_inputs
    def fromutc(self, dt):
        self.calls.append(dt)
        return dt


def test_fromutc_rejects_mismatched_tzinfo_with_valueerror():
    tz = _RecordingTz()
    other = _FixedOffset(60)
    dt = datetime(2020, 1, 1, 12, 0, tzinfo=other)

    with pytest.raises(ValueError):
        tz.fromutc(dt)

    assert tz.calls == []


def test_fromutc_rejects_naive_datetime_with_valueerror():
    tz = _RecordingTz()
    dt = datetime(2020, 1, 1, 12, 0)

    with pytest.raises(ValueError):
        tz.fromutc(dt)

    assert tz.calls == []


def test_fromutc_accepts_matching_tzinfo_and_calls_wrapped():
    tz = _RecordingTz()
    dt = datetime(2020, 1, 1, 12, 0, tzinfo=tz)

    result = tz.fromutc(dt)

    assert result is dt
    assert tz.calls == [dt]


def test_fromutc_rejects_non_datetime_with_typeerror():
    tz = _RecordingTz()

    with pytest.raises(TypeError):
        tz.fromutc("not a datetime")

    assert tz.calls == []

