import pytest

from markupsafe import Markup


def test_split_maxsplit_zero_unsplit() -> None:
    # maxsplit=0 must leave the string unsplit: one element, the whole string.
    result = Markup("a b c").split(maxsplit=0)
    assert result == [Markup("a b c")]
    assert len(result) == 1


def test_split_maxsplit_zero_with_sep() -> None:
    result = Markup("a,b,c").split(",", 0)
    assert result == [Markup("a,b,c")]


