import pytest

from jinja2 import Environment
from jinja2.filters import do_truncate


@pytest.fixture
def env():
    return Environment()


def test_short_string_unchanged(env):
    # len(s) < length + leeway -> returned unchanged
    assert do_truncate(env, "foo bar baz qux", 20) == "foo bar baz qux"


def test_killwords_truncation(env):
    # killwords cuts at length - len(end) and appends end
    assert do_truncate(env, "foo bar baz qux", 9, True) == "foo ba..."


def test_word_boundary_truncation(env):
    # non-killwords discards the trailing partial word
    assert do_truncate(env, "foo bar baz qux", 9) == "foo..."


def test_zero_leeway_exact_length(env):
    # With leeway 0, a string exceeding length is truncated to exactly length chars
    result = do_truncate(env, "foo bar baz qux", 11, False, "...", 0)
    assert result == "foo bar..."
    assert len(result) == 11


def test_leeway_prevents_truncation(env):
    # len(s) == 11, length 11, default leeway 5 -> unchanged
    assert do_truncate(env, "foo bar baz qux", 11) == "foo bar baz qux"


def test_custom_end_marker(env):
    assert do_truncate(env, "foo bar baz qux", 9, True, "!") == "foo bar !"


def test_default_leeway_from_policy(env):
    # default leeway comes from env.policies['truncate.leeway']
    assert env.policies["truncate.leeway"] == 5
    # len 12, length 8, leeway 5 -> 12 < 13 so unchanged
    assert do_truncate(env, "abcdefghijkl", 8) == "abcdefghijkl"
    # len 14, length 8, leeway 5 -> 14 >= 13 so truncated
    assert do_truncate(env, "abcdefghijklmn", 8, True) == "abcde..."


def test_length_less_than_end_raises(env):
    with pytest.raises(AssertionError):
        do_truncate(env, "foo bar", 2)


def test_negative_leeway_raises(env):
    with pytest.raises(AssertionError):
        do_truncate(env, "foo bar baz qux", 9, False, "...", -1)

