from datetime import datetime, timedelta, tzinfo

import pytest

from dateutil.tz._common import _validate_fromutc_inputs


class _RecordingTz(tzinfo):
    """A tzinfo whose fromutc is wrapped by _validate_fromutc_inputs."""

    def __init__(self):
        self.calls = []

    def utcoffset(self, dt):
        return timedelta(0)

    def dst(self, dt):
        return timedelta(0)

    def tzname(self, dt):
        return "recording"

    @_validate_fromutc_inputs
    def fromutc(self, dt):
        self.calls.append(dt)
        return dt + timedelta(hours=1)


class _OtherTz(tzinfo):
    def utcoffset(self, dt):
        return timedelta(hours=2)

    def dst(self, dt):
        return timedelta(0)

    def tzname(self, dt):
        return "other"


def test_mismatched_tzinfo_raises_value_error_and_skips_conversion():
    tz = _RecordingTz()
    other = _OtherTz()
    dt = datetime(2020, 1, 1, 12, 0, tzinfo=other)

    with pytest.raises(ValueError):
        tz.fromutc(dt)

    assert tz.calls == []


def test_naive_datetime_raises_value_error_and_skips_conversion():
    tz = _RecordingTz()
    dt = datetime(2020, 1, 1, 12, 0)

    with pytest.raises(ValueError):
        tz.fromutc(dt)

    assert tz.calls == []


def test_matching_tzinfo_calls_wrapped_conversion():
    tz = _RecordingTz()
    dt = datetime(2020, 1, 1, 12, 0, tzinfo=tz)

    result = tz.fromutc(dt)

    assert result == datetime(2020, 1, 1, 13, 0, tzinfo=tz)
    assert tz.calls == [dt]


def test_non_datetime_input_raises_type_error_and_skips_conversion():
    tz = _RecordingTz()

    with pytest.raises(TypeError):
        tz.fromutc("2020-01-01T12:00:00")

    assert tz.calls == []
